const payload = $input.first().json;
if (!Array.isArray(payload.results) || !payload.results.length) throw new Error('No Sproutify Home sync result returned');
const failed = payload.results.filter(result => !result.ok);
if (failed.length) throw new Error('Sproutify Home App Store sync failed; inspect the app status in Trellis');
return $input.all();
